const Default = () => {
  const [open, setOpen] = useState(false);
  return (
    <>
      <Button onClick={() => setOpen(true)}>Show balances in USD</Button>
      <FiatConsentDialog
        open={open}
        onOpenChange={setOpen}
        onAccept={() =>
          new Promise((resolve) => setTimeout(resolve, 800))
        }
      />
    </>
  );
};

const Open = () => {
  const [open, setOpen] = useState(true);
  return (
    <FiatConsentDialog
      open={open}
      onOpenChange={setOpen}
      onAccept={async () => {}}
    />
  );
};
